import math

def check_condition(n, a):
    """Checks if k divides C, where k = n - 2a and C = binomial(a-1, k-1)."""

    # 1. Check if a is valid (floor(n/a) == 2)
    if n / a < 2 or n / a >= 3:
        return False, "Invalid a for n"

    # 2. Calculate k
    k = n - 2 * a

    # k must be a positive divisor for the check to be meaningful in this context.
    if k <= 0:
        return False, f"k is non-positive: k={k}"

    # 3. Calculate the binomial coefficient C = binomial(a-1, k-1)
    # We need k-1 >= 0 and a-1 >= k-1
    if k - 1 > a - 1:
        C = 0 # By definition, C is 0 if the lower index is greater than the upper index
    else:
        C = math.comb(a - 1, k - 1)

    # 4. Check divisibility: k must divide C
    is_divisible = (C % k == 0)

    return is_divisible, {
        'n': n,
        'a': a,
        'k': k,
        'C': C,
        'divisible': is_divisible
    }

